<?php
$page_title='Payment Records'; require_once __DIR__.'/header.php';
$search=trim($_GET['search']??''); $from=$_GET['from']??''; $to=$_GET['to']??''; $service=(int)($_GET['service']??0); $where=[];$params=[];
if($search!==''){$where[]='(p.patient_name LIKE ? OR p.service_name LIKE ? OR p.payment_ref LIKE ?)';array_push($params,"%$search%","%$search%","%$search%");} if($from!==''){$where[]='DATE(p.payment_datetime)>=?';$params[]=$from;} if($to!==''){$where[]='DATE(p.payment_datetime)<=?';$params[]=$to;} if($service){$where[]='p.service_id=?';$params[]=$service;}
$sql='SELECT p.*,s.service_item FROM payments p LEFT JOIN services s ON p.service_id=s.id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.payment_datetime DESC';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$total=array_sum(array_map(fn($r)=>$r['status']==='active'?$r['amount']:0,$rows));$services=db()->query('SELECT id,service_item FROM services ORDER BY service_item')->fetchAll();
?>
<style>.filter-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.5fr auto;gap:9px;align-items:end}.record-actions{display:flex;gap:9px;align-items:center}.cancelled{text-decoration:line-through;color:#87938f}.status-cancelled{color:#a44545;background:#f9e4e4;padding:4px 8px;border-radius:12px;font-size:11px;font-weight:bold}@media(max-width:850px){.filter-grid{grid-template-columns:1fr 1fr}.filter-grid .search-field{grid-column:span 2}}</style>
<div class="list-head"><div><span>PAYMENT HISTORY</span><h2>Payment records</h2><p><?=count($rows)?> record<?=count($rows)!=1?'s':''?> · <?=peso((float)$total)?> active total</p></div><a class="primary" href="payment.php">＋ Record Payment</a></div><div class="panel"><form class="search filter-grid"><label class="search-field">Search<input name="search" value="<?=e($search)?>" placeholder="Patient, service, or reference"></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><label>Service<select name="service"><option value="">All services</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$service===$s['id']?'selected':''?>><?=e($s['service_item'])?></option><?php endforeach?></select></label><button class="secondary">Filter</button></form><?php if(!$rows):?><div class="empty">No payment records found.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Patient / Client</th><th>Service</th><th>Amount</th><th>Date & Time</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="<?=$r['status']==='cancelled'?'cancelled':''?>"><td><strong><?=e($r['payment_ref'])?></strong></td><td><?=e($r['patient_name'])?><br><small><?=e($r['patient_phone']?:'')?></small></td><td><?=e($r['service_item']?:$r['service_name'])?></td><td class="amount"><?=peso((float)$r['amount'])?></td><td><?=date('M j, Y · g:i A',strtotime($r['payment_datetime']))?></td><td><?=$r['status']==='cancelled'?'<span class="status-cancelled">Cancelled</span>':'Active'?></td><td><div class="record-actions"><a href="receipt.php?id=<?=$r['id']?>">Receipt</a><?php if(is_admin()&&$r['status']==='active'):?><a href="edit_payment.php?id=<?=$r['id']?>">Edit</a><?php endif?></div></td></tr><?php endforeach?></tbody></table></div><?php endif?></div><?php require __DIR__.'/footer.php';
